'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { createTag, getTagIdentity, TAG_SIZE } = require('../lib/tags');

// Frozen outputs from unmodified node-ld dist/lib/CharCrypto.js + PWDGen.js.
// Upstream source provenance and blob IDs are in vendor/node-ld/UPSTREAM.md.
// These are independent fixtures, not outputs generated by the code under test.
const vectors = [
  ['04112233445580', 1, '598e9b7556ae34ba', 'c29ef159'],
  ['04112233445580', 2, '08aa5a8446ee6b6b', 'c29ef159'],
  ['04112233445580', 57, '56cd48c24f54cb16', 'c29ef159'],
  ['04112233445580', 769, '98de8bcafb33c656', 'c29ef159'],
  ['04deadbeef0180', 1, 'd69d9328ac36082c', '700560f4'],
  ['04deadbeef0180', 57, 'cf5be939e8cc0026', '700560f4'],
  ['04deadbeef0180', 769, '5cb8aab809622407', '700560f4'],
];

test('character bytes and password match frozen upstream crypto vectors', () => {
  for (const [uid, id, encrypted, pwd] of vectors) {
    const tag = createTag({ id, type: 'character', uid });
    assert.equal(tag.length, TAG_SIZE);
    assert.equal(tag.subarray(144, 152).toString('hex'), encrypted);
    assert.equal(tag.subarray(172, 176).toString('hex'), pwd);
    assert.deepEqual(getTagIdentity(tag), { id, type: 'character', uid });
  }
});

test('imports independently assembled character file with emulator header bytes', () => {
  const tag = Buffer.alloc(180);
  Buffer.from('04dead01beef0180', 'hex').copy(tag);
  Buffer.from('d69d9328ac36082c', 'hex').copy(tag, 144);
  assert.deepEqual(getTagIdentity(tag), { id: 1, type: 'character', uid: '04deadbeef0180' });
});

test('vehicle layout uses clear ID and marker, without fabricated upgrades', () => {
  const tag = createTag({ id: 1006, type: 'vehicle', uid: '04112233445580' });
  assert.equal(tag.readUInt32LE(144), 1006);
  assert.equal(tag.subarray(152, 156).toString('hex'), '00010000');
  assert.equal(tag.readUInt32LE(140), 0);
  assert.equal(tag.readUInt32LE(148), 0);
  assert.deepEqual(getTagIdentity(tag), { id: 1006, type: 'vehicle', uid: '04112233445580' });
});

test('vehicle identity survives game writes and parsing never rewrites data', () => {
  const tag = createTag({ id: 1006, type: 'vehicle', uid: '04112233445580' });
  tag.writeUInt32LE(0xefffffff, 140);
  tag.writeUInt32LE(1007, 144);
  tag.writeUInt32LE(0x12345678, 148);
  const before = Buffer.from(tag);
  assert.equal(getTagIdentity(tag).id, 1007);
  assert.deepEqual(tag, before);
});

test('blank vehicle tags can be populated by the game', () => {
  const tag = createTag({ id: 0, type: 'vehicle' });
  assert.equal(getTagIdentity(tag).id, 0);
  tag.writeUInt32LE(1006, 144);
  assert.equal(getTagIdentity(tag).id, 1006);
});

test('new copies of the same character have independent UIDs', () => {
  const first = getTagIdentity(createTag({ id: 1, type: 'character' }));
  const second = getTagIdentity(createTag({ id: 1, type: 'character' }));
  assert.notEqual(first.uid, second.uid);
  assert.match(first.uid, /^04[0-9a-f]{10}80$/);
});

test('Buffer UID input is accepted and is not mutated', () => {
  const uid = Buffer.from('04112233445580', 'hex');
  const before = Buffer.from(uid);
  const tag = createTag({ id: 2, type: 'character', uid });
  assert.deepEqual(uid, before);
  assert.equal(getTagIdentity(tag).uid, uid.toString('hex'));
});

test('invalid inputs fail before creating a usable tag', () => {
  for (const id of [-1, 0, 1000, NaN, Infinity, 1.5, '1']) {
    assert.throws(() => createTag({ id, type: 'character' }));
  }
  for (const id of [-1, 1, 999, 65536, NaN, 1000.5]) {
    assert.throws(() => createTag({ id, type: 'vehicle' }));
  }
  for (const uid of ['', 'zz112233445580', '0411223344558', Buffer.alloc(6), Buffer.alloc(8), null]) {
    assert.throws(() => createTag({ id: 1, type: 'character', uid }));
  }
  assert.throws(() => createTag({ id: 1, type: 'other' }));
  assert.throws(() => createTag());
  for (const invalid of [Buffer.alloc(179), Buffer.alloc(181), Buffer.alloc(180), new Uint8Array(180)]) {
    assert.throws(() => getTagIdentity(invalid));
  }
});

test('damaged encrypted identity and invalid vehicle IDs are rejected', () => {
  const tag = createTag({ id: 1, type: 'character', uid: '04112233445580' });
  tag[148] ^= 1;
  assert.throws(() => getTagIdentity(tag));
  const vehicle = createTag({ id: 1006, type: 'vehicle' });
  vehicle.writeUInt32LE(4, 144);
  assert.throws(() => getTagIdentity(vehicle));
});
